package com.visionerp.controller; import com.visionerp.repository.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {final EmployeeRepository e;final AttendanceRepository a;final VisitorRepository v;final DepartmentRepository d;public DashboardController(EmployeeRepository e,AttendanceRepository a,VisitorRepository v,DepartmentRepository d){this.e=e;this.a=a;this.v=v;this.d=d;}@GetMapping("/summary")public Map<String,Object> summary(){LocalDate day=LocalDate.now();return Map.of("employees",e.countByActiveTrue(),"present",a.countByWorkDateAndStatus(day,"PRESENT"),"late",a.countByWorkDateAndStatus(day,"LATE"),"absent",Math.max(0,e.countByActiveTrue()-a.countByWorkDateAndStatus(day,"PRESENT")-a.countByWorkDateAndStatus(day,"LATE")),"visitorsToday",v.countByStatus("CHECKED_IN"),"departments",d.count());}}
